Create a new file called `cartSlice.js` with the following content:

```javascript
import { createSlice } from '@reduxjs/toolkit';

export const cartSlice = createSlice({
  name: 'cart',
  initialState: {
    items: [],
    subtotal: 0,
    tax: 0,
    total: 0,
  },
  reducers: {
    addItem(state, action) {
      state.items.push(action.payload);
      state.subtotal += action.payload.price;
      state.total = state.subtotal + (state.subtotal * state.tax);
    },
    removeItem(state, action) {
      const index = state.items.findIndex(item => item.id === action.payload.id);
      if (index >= 0) {
        state.items.splice(index, 1);
        state.subtotal -= action.payload.price;
        state.total = state.subtotal + (state.subtotal * state.tax);
      }
    },
    updateItem(state, action) {
      const index = state.items.findIndex(item => item.id === action.payload.id);
      if (index >= 0) {
        state.items[index].quantity += action.payload.quantity;
        state.subtotal += action.payload.quantity * action.payload.price;
        state.total = state.subtotal + (state.subtotal * state.tax);
      }
    },
    calculateTax(state, action) {
      state.tax = action.payload.tax;
      state.total = state.subtotal + (state.subtotal * state.tax);
    },
  },
});

export const { addItem, removeItem, updateItem, calculateTax } = cartSlice.actions;
```

